import React from 'react';
import { Card, CardContent } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';

export default function BlogSection() {
  const posts = [
    {
      category: 'React JS',
      date: 'Dec 12, 2025',
      title: 'Frontend vs. Backend: Which Path Should You Choose?',
      image: 'https://ext.same-assets.com/498039404/1747523574.jpeg',
    },
    {
      category: 'Development',
      date: 'Dec 27, 2025',
      title: '11 SEO for Developers: Optimizing Websites for Better Rankings',
      image: 'https://ext.same-assets.com/498039404/1192741041.png',
    },
    {
      category: 'Freelancing',
      date: 'May 31, 2025',
      title: 'Working Remotely as a Full Stack Developer: My Workflow & Tools',
      image: 'https://ext.same-assets.com/498039404/688989959.png',
    },
  ];

  return (
    <section className="py-20 container mx-auto px-6 lg:px-16">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center gap-4 mb-12">
          <span className="text-sm text-gray-400">// Blogs</span>
          <div className="flex-1 h-px bg-gray-600"></div>
        </div>
        <h2 className="text-4xl lg:text-5xl font-bold mb-16 text-white">Developer Insights & Ideas</h2>
        <div className="grid md:grid-cols-3 gap-8 mb-12">
          {posts.map((post, index) => (
            <Card key={index} className="overflow-hidden bg-gray-900/50 border-gray-600">
              <div className="aspect-video overflow-hidden">
                <img src={post.image || '/placeholder.svg'} alt={post.title} className="w-full h-full object-cover transition-transform duration-300 hover:scale-105" />
              </div>
              <CardContent className="p-6">
                <div className="flex items-center gap-2 mb-3">
                  <Badge variant="secondary" className="text-xs bg-teal-500/20 text-teal-500">
                    {post.category}
                  </Badge>
                  <span className="text-xs text-gray-400">{post.date}</span>
                </div>
                <h3 className="font-semibold leading-tight text-white">{post.title}</h3>
              </CardContent>
            </Card>
          ))}
        </div>
        <div className="text-center">
          <Button className="rounded-full bg-teal-500 hover:bg-teal-600 text-white">View More Blogs</Button>
        </div>
      </div>
    </section>
  );
}
